const { setFlagsFromString } = require('node:v8')
const { runInNewContext } = require('node:vm')
const { setImmediate } = require('node:timers/promises')

setFlagsFromString('--expose-gc')
const gc = runInNewContext('gc')
const reference = new WeakRef(module.parent)
const filename = module.parent.filename

module.exports = async function collect() {
  for (let i = 0; i < 10; i++) {
    await setImmediate()
    gc()
  }
  const parent = reference.deref()
  return {
    retained: parent !== undefined,
    cached: parent !== undefined && require.cache[filename] === parent,
  }
}
